def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.where(rem >= 0, np.exp(-rem), -1.0)
    if scores.size > 0:
        scores[-1] = 0.05 if item <= bins[-1] else -1.0
    return scores

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.where(rem >= 0, 1.0 / (1.0 + rem), -1.0)
    if scores.size > 0:
        scores[-1] = 0.1 if item <= bins[-1] else -1.0
    return scores

